// v2.2 offline interaction source. No model, network, CLI, or GitHub execution.
function coordSeed(){return {version:1,secretaryOnline:true,chat:[{role:'secretary',text:'我帮你看进度、联系负责人和跟进交付；不替开发者写代码、运行测试或作接收结论。下方是固定交互示例，不是已接通的 AI。'}],intake:null,delivery:null,followups:[],newWorkPaused:false};}
function secretarySay(role,text){s.coord.chat.push({role,text,at:time()});save();}
function secretaryAllowed(action){return ['read','message','followup','request_intake','queue_preference'].includes(action);}
function renderSecretary(){const c=s.coord;return pageHead('YOUR WORK SECRETARY','事情交给我跟进，技术交给负责人。','独立 Codex 会话的目标交互 · 当前离线示例；不编码、不验收、不合并。',btn(icon('plus')+'新任务接入','coord-new','','primary'))+`<div class="secretary-grid"><section class="card secretary-chat"><div class="between"><div><h3>工作秘书 ${badge(c.secretaryOnline?'示例待命':'示例离线',c.secretaryOnline?'green':'amber')}</h3><div class="tiny sub">Codex App Server · 真实接入尚未实现</div></div>${btn('职责与工具','coord-roles','','ghost sm')}</div><div class="secretary-log" role="log" aria-label="秘书示例对话">${c.chat.map(m=>`<div class="secretary-msg ${m.role==='user'?'user':''}"><small>${m.role==='user'?'你':'工作秘书'} · ${esc(m.at||'示例起点')}</small>${esc(m.text)}</div>`).join('')}</div><div class="secretary-compose"><div class="secretary-chips">${['总览进度','新增历史导出','优先收尾','催接收'].map(t=>btn(t,'sec-example',t,'sm')).join('')}</div><label class="field"><span>给秘书的安排</span><textarea id="secretary-input" placeholder="例如：新增历史导出，先与在途任务协调。"></textarea></label><div class="between wrap"><span class="tiny sub">仅识别上方固定示例；其他文本不会执行。Ctrl/⌘ + Enter 发送。</span>${btn('发送安排 '+icon('send',true),'sec-send','','primary',!c.secretaryOnline)}</div></div></section><aside class="stack"><section class="card pad"><div class="between"><h3>我在跟进</h3>${badge(c.followups.length+' 项')}</div>${c.followups.length?c.followups.map(x=>`<div class="coord-member"><b>${esc(x.title)}</b><p class="coord-caption">${esc(x.status)}</p>${btn('查看交接','navigate','coordination','ghost sm')}</div>`).join(''):'<p class="coord-caption space-top">没有新的安排。创建一个新任务，查看怎样联系在途负责人。</p>'}</section><section class="card pad"><div class="up">JOINT DELIVERY</div><h3 class="space-top">先协调共享部分，再开始写入</h3><p class="coord-caption space-top">秘书找人；任务负责人定接口、消费者与责任；接收者确定候选合入安排。</p>${btn('接入协调与共同交付','navigate','coordination','soft space-top')}</section><section class="card pad"><h3>秘书不是开发总管</h3><p class="coord-caption space-top">任务通过工作台直接联系，不等秘书转述。秘书离线，既有开发、消息和接收继续。</p>${btn(c.secretaryOnline?'模拟秘书离线':'恢复秘书','sec-toggle','','ghost sm')}${btn('查看原 PR 队列','navigate','overview','ghost sm')}${c.newWorkPaused?btn('恢复已获准的新实施','sec-resume-work','','soft sm'):''}</section></aside></div>`;}
function secretarySend(text){const c=s.coord;if(!c.secretaryOnline)return toast('秘书当前离线；可直接使用任务与接收界面。','alert');text=String(text||'').trim();if(!text)return;secretarySay('user',text);if(s.mode==='readonly'&&!/总览|进度|状态/.test(text)){secretarySay('secretary','只读模式：仅整理和展示，不登记派发、改队列或发交接。');render();return;}if(/新增|新任务/.test(text)){secretarySay('secretary','我先整理接入请求，联系现有负责人核对共享接口。这里只创建协调任务，不会立即开始共享代码写入。');render();return openCoordIntake();}if(/合并全部|跳过|替.*审核|写代码|运行测试/.test(text)){secretarySay('secretary','这不在秘书权限内。可以联系任务负责人或 PR 接收者，但我不能作技术判断、运行验证或越过合并条件。');}else if(/优先收尾|暂停新任务/.test(text)){c.newWorkPaused=true;secretarySay('secretary','已登记本地示例的“优先收尾”安排：暂停新增实施派发，不中断现有运行。等待的必要依赖仍由接收方判断；未修改任务目标或预算。');event('秘书登记收尾偏好','只影响新实施派发，不中断已有执行。');}else if(/催接收/.test(text)){const key='receiver-followup';if(!c.followups.some(f=>f.id===key)){c.followups.push({id:key,title:'请接收者检查已就绪候选',status:'请求已登记；尚未取得接收结论'});const op=operation('secretary-followup',key,'本地示例：联系 PR 接收角色，不直接合并');finish(op,'已登记交接请求；未声称接收者已经完成');}secretarySay('secretary','已登记给接收角色的跟进事项。重复催办不会新增一份同义请求；候选是否可合仍由接收者判断。');}else if(/总览|进度|状态/.test(text)){const pendingPR=Object.values(s.prs).filter(p=>!p.merged).length;secretarySay('secretary',`当前示例有 ${pendingPR} 项未合入 PR。${c.intake?'新任务协调：'+coordState()+'。':'尚无新增接入任务。'}来源接口 #160 的技术问题由原负责人处理；我不会把运行完成或测试数量当作用户成果。详情可从原 PR 队列展开。`);}else{secretarySay('secretary','这份离线原型没有连接模型，无法理解任意指令；没有执行动作。可用上方四个示例查看未来的交互方式。');}render();}
function coordState(){const i=s.coord.intake;if(!i)return '尚未开始';if(i.approved)return '共享边界已对齐，可按范围实施';return '待 '+['A','B','receiver'].filter(k=>i.acks[k]!==i.revision).map(k=>k==='receiver'?'接收者核定':k+' 方反馈').join('、');}
function openCoordIntake(){if(s.coord.intake)return navigate('coordination');openModal('新增任务：先与在途任务协调',`<div class="notice amber">这一步只登记已提出的需求与协调对象，不授予共享写入、新费用或合并权。</div><label class="field space-top"><span>任务目标</span><input id="coord-title" value="指定公司与历史财年导出 CSV"></label><label class="field"><span>现有相关任务（固定示例，非完整自动影响分析）</span><select id="coord-peer"><option value="40">#40 单公司链路 · A / Codex</option></select></label><label class="field"><span>希望双方核对什么</span><textarea id="coord-boundary">年份参数、金额单位、失败含义、旧结果复用；A 维护公共接口，B 负责历史消费。未回复不算同意。</textarea></label>`,footerHint('仅本地示例。新任务可调查，冲突部分不能立即写入。',btn('登记并联系相关负责人','coord-create','','primary')),'任务接入 / 不是技术审批',false,{kind:'coord-intake'});}
function coordCreate(){if(s.mode==='readonly')return formError('只读模式不登记派发，请在原型设置切换模式。');if(s.coord.intake)return navigate('coordination');const title=$('#coord-title').value.trim(),boundary=$('#coord-boundary').value.trim();if(!title||!boundary)return formError('请填写目标与需核对的边界。');for(const [id,role,engine] of [['sec-1','工作秘书（仅联络）','Codex'],['rx-1','独立 PR 接收者','Claude Code']]){s.sessions[id]={id,role,engine,top:50,tasks:[],workspace:'/demo/coord/'+id,branch:'',native:'demo-'+id,state:'idle',event:'独立角色的固定示例',caps:['observe','send'],turn:1,todos:[]};}s.coord.intake={id:'IN-70',title,boundary,revision:1,acks:{},approved:false};s.coord.delivery={id:'X1',revision:1,title,mode:'sequence',accepted:false,members:[201,202,203],later:null};s.tasks[70]={id:70,parent:50,title,owner:null,mode:null,pr:202,scope:'scope-50-r1',goal:title};const def=(id,issue,title,deps)=>{const p=clone(P(102));Object.assign(p,{id,issue,title,head:hex('e'+id+'001'),source:'task/x1-'+id,target:'main',plannedTarget:'main',scope:T(issue).scope,phase:'working',draft:true,recordHead:null,selfReview:false,review:null,tests:null,findings:[],decisions:[],deps,history:[],merged:null,acceptance:null,report:null,baseAssessment:null,incident:false,summary:'X1 固定演练候选；作者声明、独立审核和接收结论仍需分别取得。'});s.prs[id]=p;};def(201,42,'A1 · 增加兼容年份接口',[]);def(202,70,'B1 · 历史消费者接入（未启用入口）',[{type:'pr',id:201,target:'main'}]);def(203,43,'A2 · 启用指定年份导出',[{type:'pr',id:202,target:'main'}]);s.coord.followups.push({id:'IN-70',title:'新历史任务与在途单公司任务协调',status:'联系 A、B 与接收者；未开始新共享写入'});coordSend('A');coordSend('B');coordSend('receiver');secretarySay('secretary','已登记 X1 接入，向 A、B 与接收者分别发出协调请求。A/B 定技术边界；接收者核对每一步是否可安全合入。没有新建写入执行者。');closeModal();navigate('coordination');}
function coordSend(who){const i=s.coord.intake,tag=`CO-${i.revision}-${who}`;if(s.messages.some(m=>m.id===tag))return false;const target=who==='A'?'cx-A':who==='B'?'cc-B':'rx-1';const m={id:tag,from:'sec-1',to:target,task:70,title:who==='receiver'?'请接收角色核定 X1 合入安排':'请 '+who+' 方核对共享边界',body:`X1 r${i.revision}：${i.boundary}\n${who==='receiver'?'接收角色由独立 Claude Code 上下文承担；此处仅展示模拟回执。':'请说明接口、未提交工作、责任与消费者验证。'}\n正式约定应回原 Issue，当前仅本地演练。`,type:'request',status:'delivered',at:time(),nativeTo:S(target).native,reply:null};s.messages.unshift(m);const op=operation('coord-message',tag,'工作台投递示例');finish(op,'注入示例送达回执；不代表已对齐或允许写入');return true;}
function coordAck(who,revision=s.coord.intake?.revision){const i=s.coord.intake;if(!i||s.mode==='readonly'||!['A','B','receiver'].includes(who)||revision!==i.revision)return false;if(who==='receiver'&&['A','B'].some(k=>i.acks[k]!==i.revision)){toast('先取得 A/B 对当前版本的反馈；秘书不能代替技术协调。','alert');return false;}i.acks[who]=i.revision;const m=s.messages.find(m=>m.id===`CO-${i.revision}-${who}`);if(m){m.status='replied';m.reply=who==='receiver'?'接收者模拟结论：A1 兼容可先合；B1 只等 A1，不等 A 的整个 Issue；A2 等消费者及组合验证。':'模拟 '+who+' 反馈：按当前边界分工；共享接口一位写入者，消费端独立验证。';}i.approved=['A','B','receiver'].every(k=>i.acks[k]===i.revision);const f=s.coord.followups.find(f=>f.id===i.id);f.status=coordState();event('协调反馈已登记（模拟）',who+' 对 X1 r'+i.revision+' 的意见；不等于代码已交付');render();return true;}
function coordWriteAllowed(){return !!s.coord.intake?.approved&&!s.coord.newWorkPaused;}
function coordCurrentPlan(){return !!s.coord.intake?.approved&&s.coord.delivery?.revision===s.coord.intake.revision;}
function renderCoordination(){const i=s.coord.intake,d=s.coord.delivery;if(!i)return pageHead('INTAKE / DELIVERY','新任务接入与共同交付','先找相关负责人；不要把同属功能 X 误当成必须同时合并。',btn('创建接入示例','coord-new','','primary'))+`<section class="card pad"><h3>这里会显示什么？</h3><p class="coord-caption space-top">在途任务 → 相关开发者反馈 → 接收安排 → 精确 PR 前置 → 最终用户场景。秘书只协调，接收者决定最小安全合入范围。</p></section>`;return pageHead('INTAKE / JOINT DELIVERY',esc(i.title),'X1 第一批交付 · 不是等待整个 Issue 完成，也不是每两小时合并全部 PR。',btn('回到工作秘书','navigate','secretary','ghost')+btn('加入后续扩展 X2','coord-expand','',''))+`<div class="coord-grid"><section class="card pad"><div class="between"><h2>接入协调</h2>${badge('r'+i.revision,i.approved?'green':'amber')}</div><p class="coord-caption space-top">${esc(i.boundary)}</p><div class="coord-proof space-top">${esc(coordState())}<br>共享写入：${coordWriteAllowed()?'可进入已授权实施；仍需工作区检查':'未放行；独立调查可继续'}</div>${[['A','既有负责人 A · Codex'],['B','新任务负责人 B · Claude Code'],['receiver','独立接收者 · Claude Code']].map(([k,n])=>`<div class="coord-step"><div class="between"><b>${n}</b>${badge(i.acks[k]===i.revision?'本版已反馈':'待本版反馈',i.acks[k]===i.revision?'green':'amber')}</div><p>${k==='receiver'?'核对中间版本、真实消费者和合入前置，不以作者自报直接放行。':'核对实际在途工作、接口与失败含义；口头确认不冒充代码证据。'}</p>${btn('注入'+(k==='receiver'?'接收者':k+' 方')+'模拟反馈','coord-ack',k,'sm',i.acks[k]===i.revision)}</div>`).join('')}<div class="row wrap">${btn('开始已对齐任务','coord-start','','primary',!coordWriteAllowed()||!!T(70).owner)}${btn('模拟接口发生实质变化','coord-change','','ghost sm')}</div><p class="tiny sub space-top">所有按钮仅改变离线状态。真实开发前，当前范围和共同约定必须已正式采用。</p></section><section class="card pad"><div class="between"><h2>共同交付 X1</h2>${badge(d.accepted?'用户场景已验收':'尚未完成',d.accepted?'green':'amber')}</div><p class="coord-caption space-top">技术牵头：A；参与任务：#40 / #70；接收：独立 PR Agent。当前接收安排：${d.mode==='sequence'?'兼容基础 → 消费者 → 用户入口':'需要接收者另建最小集成候选；普通逐个主干合并已阻止'}。</p>${d.members.map(id=>{const p=P(id),deps=p.deps.map(x=>'PR #'+x.id).join('、');return `<div class="coord-member"><div class="between"><h3>${esc(p.title)}</h3>${badge(...labelFor(p))}</div><p class="coord-caption">${id===201?'独立兼容能力可先合，不等待 B 全部完成':id===202?'只等 A1 接口到位，不等 Issue A 结束':'等 B1 与真实组合场景，之后才可启用'}。<br>本次目标：${esc(p.target)} · ${deps?'前置：'+deps:'没有整项 Issue 等待'}。</p><div class="row">${btn('打开 PR 与证据','pr',id,'sm')}${!p.merged?btn('注入候选检查（模拟）','coord-fixture',id,'ghost sm'):''}</div></div>`;}).join('')}<div class="row wrap space-top">${btn('通知接收者复核就绪候选','coord-wake','','soft')}${btn(d.mode==='sequence'?'请求改用最小集成候选':'接收者确认保留顺序方案（模拟）',d.mode==='sequence'?'coord-atomic':'coord-sequence','','ghost sm')}${btn('登记最终用户场景','coord-accept','','primary',!d.members.every(id=>P(id).merged&&!P(id).incident))}</div>${d.later?`<div class="coord-proof space-top"><b>X2 后续扩展</b><br>${esc(d.later)}。不会静默改变 X1 的完成边界。</div>`:''}<div class="role-boundary space-top">检查由事件唤醒，低频补查只补遗漏。秘书不能设置 PASS；不能把两次快速合并冒充一次原子变更。</div></section></div>`;}
function coordPrepare(id){if(!canRecord())return;const p=P(+id);if(!coordCurrentPlan())return toast('先对齐当前版本；不能用旧反馈准备新候选。','alert');p.selfReview=true;p.draft=false;p.recordHead=p.head;p.phase='queued';p.review={id:'DEMO-REV-'+p.id+'-'+s.coord.delivery.revision,head:p.head,base:s.branches[p.target],target:p.target,scope:p.scope,verdict:'PASS',who:'独立审核者（固定注入）',evidence:'离线夹具，不是执行过的模型审核'};p.tests={head:p.head,base:s.branches[p.target],scope:p.scope,tree:hex('c'+p.id+'123'),result:'pass',count:3,passed:3,tool:'offline-fixture',inputs:'demo-x1-r'+s.coord.delivery.revision};history(p,'候选证据注入（模拟）','独立审核与测试夹具；仅用于演练接收前置','evidence');render();}
function coordRequirement(p){const d=s.coord.delivery;if(!d?.members.includes(p.id))return null;return {id:'joint-plan',title:'共同交付的接收安排适用',ok:coordCurrentPlan()&&d.mode==='sequence',detail:coordCurrentPlan()?(d.mode==='sequence'?'A/B 与接收者已对齐；仍按该 PR 的精确前置和当前证据合入':'已请求最小集成候选，不能逐个合入 main；交接收者准备'):'当前接口／范围的相关反馈未齐；仅暂停受影响推进'};}
const coordActions={
 'sec-send':()=>secretarySend($('#secretary-input')?.value),
 'sec-example':text=>secretarySend(text),
 'sec-resume-work':()=>{if(!canRecord())return;s.coord.newWorkPaused=false;event('恢复新实施派发（模拟）','仍受每项范围、协调与占用约束');render();},
 'sec-toggle':()=>{s.coord.secretaryOnline=!s.coord.secretaryOnline;render();},
 'coord-new':()=>openCoordIntake(),
 'coord-create':()=>coordCreate(),
 'coord-ack':who=>coordAck(who),
 'coord-start':()=>{if(!coordWriteAllowed())return toast('仍有协调前置或已暂停新增实施。','alert');dispatch(70,'same','/demo/worktrees/history-export-x1');},
 'coord-change':()=>{if(!canRecord())return;const i=s.coord.intake;if(!i)return;i.revision++;i.approved=false;s.coord.delivery.revision=i.revision;s.coord.delivery.accepted=false;['A','B','receiver'].forEach(coordSend);event('接口变化需重核（模拟）','旧反馈仍保留；只重核 X1 受影响部分，其他任务继续');render();},
 'coord-expand':()=>{if(!canRecord())return;if(!s.coord.delivery)return;s.coord.delivery.later='跨年份对比（待明确范围，不加入本批交付）';event('新增需求另列 X2','X1 不自动扩大范围');render();},
 'coord-fixture':id=>coordPrepare(id),
 'coord-wake':()=>{if(!canRecord())return;if(!coordCurrentPlan())return toast('等待当前版接入协调；不批量合并。','alert');const d=s.coord.delivery,ready=d.members.filter(id=>!P(id).merged&&requirements(P(id)).every(c=>c.ok)&&!P(id).draft);const key='X1-r'+d.revision+'-'+d.members.map(id=>P(id).head+':'+s.branches[P(id).target]+':'+(P(id).review?.id||'none')+':'+(P(id).tests?.tree||'none')+':'+requirements(P(id)).map(c=>c.id+'='+c.ok).join(',')).join('-');if(s.ops.some(o=>o.kind==='receiver-wake'&&o.target===key))return toast('同一候选集合已通知，不重复唤醒。','info');const op=operation('receiver-wake',key,'条件变化：接收者重新检查，不是定时全合');finish(op,ready.length?'待接收候选：'+ready.map(n=>'#'+n).join('、')+'；未执行合并':'当前没有全部条件齐备的候选；任务保持等待');toast(op.detail);render();},
 'coord-atomic':()=>{if(!canRecord())return;const d=s.coord.delivery;if(d.members.some(id=>P(id).merged))return toast('已有安全交付已合入；只对剩余范围重新规划，不追改历史。','alert');d.mode='integration-requested';event('向 PR Agent 请求最小集成候选','不连续点击合并主干；实际生成和审核集成 PR 是后续真实实现范围');render();},
 'coord-sequence':()=>{if(!canRecord()||!coordCurrentPlan())return;s.coord.delivery.mode='sequence';event('接收者恢复安全顺序方案（模拟）','兼容基础→消费者→入口；没有合并任何代码');render();},
 'coord-accept':()=>{const d=s.coord.delivery;if(!d.members.every(id=>P(id).merged&&!P(id).incident))return;openModal('X1 的最终用户场景',`<p class="coord-caption">代码都合入不代表用户目标完成。请选择本次离线注入的验收结果。</p><label class="field space-top"><span>结果</span><select id="coord-final"><option value="pending">仍待证据</option><option value="accept">用户场景通过（模拟）</option><option value="reject">用户场景不满足</option></select></label>`,footerHint('只演练结果登记，不运行真实测试。',btn('登记结果','coord-final-confirm','','primary')),'组合 / 用户验收',false,{kind:'coord-accept',revision:d.revision,versions:d.members.map(id=>P(id).merged.sha).join(',')});},
 'coord-final-confirm':()=>{if(!canRecord())return;const d=s.coord.delivery;if(modal?.kind!=='coord-accept'||modal.revision!==d.revision||modal.versions!==d.members.map(id=>P(id).merged?.sha).join(','))return formError('候选已变化，不能登记旧结论。');d.accepted=$('#coord-final').value==='accept';event('X1 用户验收（模拟）',$('#coord-final').value+'；不等于生产采纳或部署');closeModal();render();},
 'coord-roles':()=>openModal('谁做什么，谁不能做什么',`<div class="stack"><div class="role-boundary"><b>工作秘书 / Codex App Server</b><br>查询、联络、跟进、转交已批准安排。无业务代码写、任意 shell、测试、技术验收和合并工具。</div><div class="role-boundary"><b>任务负责人 / Codex 或 Claude Code</b><br>核对在途工作、协调接口、实现及消费验证。作者自测不是独立审核。</div><div class="role-boundary"><b>独立审核 / 按采用流程</b><br>固定候选与证据，新上下文，不继承作者对话。</div><div class="role-boundary"><b>PR 接收 / 独立 Claude Code</b><br>提前核对合入安排，按候选独立接收；请求由普通后台核权执行。</div><p class="coord-caption">完整 prompt 与调用契约在仓库 prompts/。这里不是已连接的权限实现。</p></div>`,footerHint('角色绑定为目标设计，原生版本和身份仍需实测。',btn('关闭','modal-close')),'角色 / 默认分工')
};
